const I18N_DICTIONARY={de:{skip_link:"Zum Hauptinhalt springen",back_to_top:"Nach oben",home_welcome_title:"Herzlich Willkommen",home_welcome_text:"Hier entstehen meine Bilder, alle von mir in liebevoller Detailarbeit handgemalt.<br>Qualität und Individualität sind mein Markenzeichen. Ich male für Dich Tierportraits oder Landschaften.",badge_handpainted:"100% Handgemalt",badge_studio:"Atelier aus Bonn",badge_shipping:"Sicherer Versand in DE",badge_detail:"Liebevolle Detailarbeit",highlights_title:"Aktuelle Highlights",highlights_intro:"Eine kleine Auswahl meiner neuesten Gemälde.",testimonials_title:"Das sagen meine Kunden",testimonials_intro:"Echte Erfahrungen & Rückmeldungen von begeisterten Meistbestellern:",cta_text:"Entdecke die Vielfalt handgemalter Originale oder lass Dein ganz persönliches Wunschmotiv anfertigen.",about_page_title:"Über mich",about_intro:"Lerne die Künstlerin hinter den Bildern kennen.",about_profile_title:"Steckbrief",about_lbl_loc:"Wohnort:",about_lbl_dog:"Frauchen von:",about_lbl_motifs:"Motive:",about_lbl_tech:"Techniken:",about_lbl_edu:"Ausbildung:",about_lbl_motive:"Motivation:",about_profile_loc:"Bonn (Bad Godesberg)",about_profile_dog:"Balou",about_profile_motifs:"Tierportraits, Lieblingsorte & Landschaften",about_profile_tech:"Acryl, Öl, Ölkreide, Mischtechniken",about_profile_edu:"Alanus Hochschule Alfter, Art Studio Bonn-Friesdorf",about_profile_motive:"Freude am Festhalten lebendiger Emotionen & Momente",about_greeting:"Hallo, ich bin Manuela,",about_subtitle:"...Künstlerin aus Bonn, Hundeliebhaberin und Frauchen von Balou",about_p1:"Ich liebe es, <strong>besondere Momente</strong>, <strong>Tiere</strong> oder <strong>Landschaften</strong> mit Pinsel und lebendigen Farben auf Leinwand oder handgeschöpftem Papier festzuhalten.",about_p2:"Meine Werke erzählen Geschichten: sei es der treue Blick eines Hundes, die Weite der französischen Atlantikküste oder historische Impressionen meiner Heimat Bonn und des Siebengebirges.",about_p3:"Ich male das, was mich berührt und fasziniert – in traditioneller <strong>Ölmalerei</strong>, leuchtenden <strong>Acrylfarben</strong> sowie feinen <strong>Ölkreide- und Multimediatechniken</strong>.",about_p4:"Jedes Bild ist ein handgemaltes Unikat, welches mit viel Liebe zum Detail und fundiertem künstlerischen Handwerk entsteht.",about_p5:'Gerne male ich auch Dein persönliches Wunschmotiv! Schau Dir meine <a href="Leistungen.html">Leistungen</a> an oder schreibe mir direkt über das <a href="Kontakt.html">Kontaktformular</a>.',services_page_title:"Leistungen",services_intro:"Individuelle Kunstwerke, ganz nach deinen Vorstellungen gestaltet.",services_offer_title:"Was ich anbiete",service_dog_title:"Dein Hund auf Leinwand",service_dog_desc:"Du hast Dir schon immer mal ein einzigartiges Portrait Deines treuen Begleiters gewünscht? Egal ob weißer Malteser oder schwarzer Labrador - jeder Hund ist ein besonderes Motiv.",service_pets_title:"Weitere tierische Freunde",service_pets_desc:"Natürlich male ich nicht nur Hunde! Auch andere tierische Familienmitglieder wie Papageien, Katzen oder auch Wildtiere sind wunderbare Motive für ausdrucksstarke Gemälde.",service_places_title:"Deine Lieblingsorte",service_places_desc:"Besondere Landschaften und Orte haben eine ganz eigene Magie. Wenn du solche Lieblingsorte hast, zaubere ich sie Dir als dauerhaftes Erinnerungsstück auf Leinwand.",service_formats_title:"Mögliche Formate",service_formats_desc:"Für Dein einzigartiges Kunstwerk biete ich verschiedene Größen und Formate an. Da alle Bilder mit viel Zeit und Liebe gemalt werden, mache ich Dir auf Anfrage gerne ein individuelles Angebot.",faq_title:"Häufig gestellte Fragen (FAQ)",faq_1_q:"Was kostet ein Bild?",faq_1_a:"Der Preis gestaltet sich nach Größe des Bildes. Die Bezahlung erfolgt gegen Vorkasse (inkl. Porto und Verpackung).",faq_2_q:"Wie lange dauert die Erstellung eines Bildes?",faq_2_a:"Je nach Technik (Acryl trocknet schneller als Öl) und aktueller Auftragslage dauert die Fertigstellung in der Regel einige Wochen. Bitte bestelle rechtzeitig, wenn es ein Geschenk sein soll!",faq_4_q_cancellation:"Widerrufsrecht bei Auftragsarbeiten",faq_4_a_cancellation:"Bei individuell nach Deinen persönlichen Wünschen und Vorgaben angefertigten Kunstwerken (wie z.&nbsp;B. Tierportraits nach Fotovorlage) besteht gemäß §&nbsp;312g Abs.&nbsp;2 Nr.&nbsp;1 BGB kein gesetzliches Widerrufsrecht, da das Werk ein eindeutig auf Dich zugeschnittenes Unikat ist. Vor Beginn und während des Malprozesses stimme ich aber alle Details und Zwischenschritte eng mit Dir ab, damit Du mit Deinem Ergebnis wunschlos glücklich bist.",gallery_page_title:"Bildergalerie",gallery_intro:"Entdecke meine handgemalten Unikate aus verschiedenen Schaffensphasen.",filter_all:"Alle Werke",filter_animals:"Tiere",filter_landscapes:"Landschaften",filter_plants:"Pflanzen",filter_other:"Sonstiges",filter_favorites:"Favoriten",search_placeholder:"Gemälde, Motive oder Techniken durchsuchen...",sort_label:"Sortierung:",sort_aria:"Galerie sortieren",sort_default:"Standard",sort_newest:"Neueste zuerst",sort_title_asc:"Titel (A-Z)",sort_title_desc:"Titel (Z-A)",gallery_empty_fav_title:"Noch keine Favoriten gemerkt.",gallery_empty_fav_text:"Klicke auf das Herz-Symbol auf den Kunstwerken, um deine persönlichen Lieblingswerke hier zu speichern.",gallery_empty_search_title:"Keine passenden Gemälde gefunden.",gallery_empty_search_text:"Versuche es mit einem anderen Suchbegriff oder setze den Kategorie-Filter zurück.",scene_label:"KI-Wandvorlage:",scene_label_short:"KI-Wandvorlage",scene_living:"Wohnzimmer",scene_living_title:"Wohnzimmer-Wand",scene_bedroom:"Schlafzimmer",scene_bedroom_title:"Schlafzimmer-Wand",scene_loft:"Loft / Beton",scene_loft_title:"Dark Loft Wand",scene_lounge:"Beige Lounge",scene_lounge_title:"Beige Lounge Wand",scene_pure:"Pur (Detail)",scene_pure_title:"Pur ohne Hintergrund",wall_drag_hint:"Ziehen zum Verschieben",lb_rotate_title:"Um 90° drehen",lb_rotate_aria:"Bild um 90 Grad drehen",lb_zoom_title:"Lupe aktivieren/deaktivieren",lb_zoom_aria:"Lupe aktivieren",lb_scale_label:"Skalierung:",lb_scale_aria:"Gemäldegröße an der Wand skalieren",lb_center_title:"Gemäldeposition auf der Wand zentrieren",lb_label_technik:"Technik:",lb_label_masse:"Maße / Format:",lb_label_kat:"Kategorie:",lb_label_herkunft:"Herkunft:",lb_val_herkunft:"Atelier Bonn",lb_label_rahmung:"Rahmung:",lb_label_status:"Verfügbarkeit:",status_verfuegbar:"Verfügbar",status_reserviert:"Reserviert",status_verkauft:"Verkauft – gerne male ich Dir ein ähnliches Motiv",lb_val_rahmung:"Sofort aufhängbar (Keilrahmen)",lb_views_title:"Weitere Ansichten:",lb_view_front:"Frontansicht",lb_view_front_title:"Frontansicht Pur",lb_view_room:"Wandansicht",lb_view_room_title:"Wand & Raumansicht",lb_view_back:"Keilrahmen",lb_view_back_title:"Rückseite & Keilrahmen",lb_view_side:"3D-Perspektive",lb_view_side_title:"3D-Seitenansicht & Textur",lb_view_artist:"Atelier",lb_view_artist_title:"Künstlerin & Atelier",lb_inquiry_aria:"Dieses Motiv als Auftrag anfragen",lb_fav_default:"Zu Favoriten",clear_search_aria:"Suche zurücksetzen",lb_btn_inquiry:"Motiv als Auftrag anfragen",lb_btn_room:"In deinem Raum ansehen",lb_btn_fav_add:"Zu Favoriten hinzufügen",lb_btn_fav_remove:"Aus Favoriten entfernen",lb_share_btn:"Gemälde teilen",lb_share_aria:"Gemälde teilen",lb_rotate:"90° Drehen",lb_zoom:"Lupe Zoom",lb_center:"Zentrieren",order_page_title:"Auftrag konfigurieren",order_intro:"In nur 4 Schritten zu deinem individuellen Kunstwerk – erhalte eine unverbindliche Preisschätzung und sende deine Anfrage direkt ab.",step_1_lbl:"Motiv",step_2_lbl:"Format",step_3_lbl:"Technik",step_4_lbl:"Zusammenfassung",step_1_heading:"Schritt 1: Wähle dein Motiv",step_1_sub:"Was soll auf deinem einzigartigen Kunstwerk zu sehen sein?",step_2_heading:"Schritt 2: Wähle das gewünschte Format",step_2_sub:"Welche Größe passt am besten in dein Zuhause?",step_3_heading:"Schritt 3: Wähle die Maltechnik",step_3_sub:"Welcher Malstil und welche Farbgebung sprechen dich am meisten an?",step_4_heading:"Schritt 4: Zusammenfassung & Anfrage",step_4_sub:"Überprüfe deine Konfiguration und sende deine unverbindliche Anfrage an Manuela ab.",contact_page_title:"Kontakt",contact_intro:"Ich freue mich über Deine Nachricht, Fragen zu meinen Werken oder Auftragsanfragen.",contact_btn_send:"Nachricht senden",map_title:"Google Maps Karte aktivieren",map_text:"Aus Datenschutzgründen wird die interaktive Karte erst nach einem Klick geladen.",map_btn:"Karte laden",imprint_page_title:"Impressum",privacy_page_title:"Datenschutzerklärung",notfound_title:"404 – Seite nicht gefunden",notfound_text:"Diese Leinwand ist noch leer. Die gesuchte Seite existiert nicht (mehr) oder wurde verschoben.",notfound_btn:"Zur Startseite",notfound_btn2:"Zur Bildergalerie",ui_close:"Schließen",ui_prev_image:"Vorheriges Bild",ui_next_image:"Nächstes Bild",ui_lightbox_label:"Bilder-Großansicht",hl_owls_aria:"Großansicht: Zwei Eulen",hl_owls_alt:"Handgemaltes Acrylbild mit zwei kleinen Eulen auf einem Ast vor blauem Hintergrund",hl_owls_caption:"Zwei Eulen (Acryl auf Leinwand)",hl_godesburg_aria:"Großansicht: Godesburg Stadtansicht",hl_godesburg_alt:"Handgemaltes Landschaftsbild der historischen Godesburg in Bonn bei Dämmerung",hl_godesburg_caption:"Godesburg Stadtansicht (Acryl auf Leinwand)",hl_rheinaue_aria:"Großansicht: Rheinaue Bonn",hl_rheinaue_alt:"Handgemaltes Acrylbild des herbstlichen Rheinaue-Sees in Bonn mit Bäumen und Spiegelungen",hl_rheinaue_caption:"Rheinaue Bonn (Acryl auf Leinwand)",hl_feld_aria:"Großansicht: Feldweg",hl_feld_alt:"Handgemaltes Acrylbild eines idyllischen Feldwegs im Sommer unter blauem Himmel",hl_feld_caption:"Feldweg im Sommer (Acryl auf Leinwand)",testi1_quote:"„Das Portrait von unserem Schäferhund Balou ist einfach fantastisch geworden. Manuela hat seinen treuen Blick exakt eingefangen. Wir sind überglücklich!“",testi1_author:"– Begeisterte Kundenfamilie",testi1_location:"Bonn-Bad Godesberg · Tierportrait in Acryl",testi2_quote:"„Ich habe ein Landschaftsbild der Rheinaue als Geschenk zur Hochzeit bestellt. Die Abstimmung war super unkompliziert und das Brautpaar war zu Tränen gerührt.“",testi2_author:"– Eine Kundin",testi2_location:"Rhein-Sieg-Kreis · Landschaftsgemälde",testi3_quote:"„Wunderschöne Arbeit! Man merkt bei jedem Pinselstrich die Liebe zum Detail. Das Bild hat jetzt einen zentralen Ehrenplatz in unserem Wohnzimmer.“",testi3_author:"– Ein Kunde",testi3_location:"Köln · Hundeportrait & Stillleben",testi_prev_aria:"Vorherige Kundenstimme",testi_next_aria:"Nächste Kundenstimme",testi_pause_aria:"Automatischen Wechsel anhalten",testi_stars_aria:"5 von 5 Sternen",testi_dot_1:"Kundenstimme 1 anzeigen",testi_dot_2:"Kundenstimme 2 anzeigen",testi_dot_3:"Kundenstimme 3 anzeigen",home_btn_gallery:"Zur Galerie",home_btn_flyer:"Flyer Download",process_h2:"Der Entstehungsprozess eines Kunstwerks",process_intro:"Kunst für dein Zuhause",process1_title:"Anfertigung mehrerer Skizzen",process1_text:"Exakte Übertragung deines Fotomotivs auf die Leinwand als feine Vorzeichnung.",process2_title:"verschiedene Farbaufträge",process2_text:"Auftrag der ersten Farbschichten für Tiefe, Schatten und charakteristische Lichtakzente.",process3_title:"feinste Ausarbeitung",process3_text:"Feinste Ausarbeitung von Augen, Fellstruktur oder Lichtreflexen sowie Schlussversiegelung.",edu_h2:"Künstlerische Ausbildung & Dozierende",edu_intro:"Fundiertes Handwerk durch kontinuierliche Weiterbildung an anerkannten Kunstakademien:",edu1_place:"Alfter bei Bonn",edu1_text:"Jahreskurs <em>„Ein Jahr für die Kunst“</em> sowie vertiefende Seminare und Intensivwochen zur künstlerischen Professionalisierung.",edu1_dozenten_label:"Dozierende:",edu2_place:"Bad Godesberg · Friesdorf",edu2_text:"Intensiver Privatunterricht in fortgeschrittenen Maltechniken, Farbenlehre, Pinselduktus und Komposition.",edu3_place:"Aachen & Bonn",edu3_text:"Fachkurse in figürlichem Zeichnen, Porträtmalerei, Landschaftsstudien und klassischer Öl- und Acrylmalerei.",tl5_title:"Kunst für Dein Zuhause",tl5_text:"Mit vielen individuellen Unikaten und vielen glücklichen Auftraggebern schaffe ich bleibende Werte und persönliche Erinnerungsstücke.",flyer_h2:"Mein Info-Flyer",flyer_text:"Klicke auf ein Bild für die Großansicht oder lade dir den Flyer als PDF herunter.",flyer_front_alt:"Vorderseite des Informationsflyers von ManuFAKTUR Schenk",flyer_back_alt:"Rückseite des Informationsflyers von ManuFAKTUR Schenk",flyer_btn:"Flyer herunterladen (PDF)",faq_3_q_ship:"Versand",faq_3_a_ship:"Nach Fertigstellung und Trocknung verschicke ich Dein Bild sicher per Post. Die genauen Versandkosten stimmen wir individuell vorab ab.",leist_cta_text:"Hast Du noch weitere Fragen oder eigene Wünsche?",leist_cta_btn1:"Auftrag konfigurieren",leist_cta_btn2:"Kontaktiere mich gerne!",kontakt_vcard_title:"Digitale Visitenkarte",kontakt_vcard_hint:"Bewege die Maus über die Karte oder tippe sie an, um sie umzudrehen.",kontakt_vcard_aria:"Digitale Visitenkarte von Manuela Schenk. Drücke Enter oder die Leertaste zum Umdrehen.",kontakt_vcard_badge:"Visitenkarte",kontakt_vcard_role:"Künstlerin & Inhaberin",kontakt_vcard_save:"Kontakt speichern (.vcf)",kontakt_vcard_pdf:"Visitenkarte (PDF)",kontakt_city:"Bonn, Deutschland",kontakt_address:"53175 Bonn, Deutschland",social_ig_label:"Folge mir auf Instagram",social_wa_label:"Schreibe mir auf WhatsApp",kontakt_prefill_text:"<strong>Deine Konfiguration wurde übertragen!</strong> Das Formular wurde mit deinen Auswahlen aus dem Konfigurator vorausgefüllt.",kontakt_label_name:"Dein Name",kontakt_ph_name:"Wie dürfen wir dich ansprechen?",kontakt_label_email:"Deine E-Mail-Adresse",kontakt_ph_email:"deine.email@beispiel.de",kontakt_label_subject:"Betreff",kontakt_opt_general:"Allgemeine Anfrage",kontakt_opt_animal:"Auftrag: Tierportrait",kontakt_opt_landscape:"Auftrag: Landschaft",kontakt_opt_purchase:"Kaufinteresse an einem Bild",kontakt_label_message:"Deine Nachricht:",kontakt_ph_message:"Deine Nachricht...",kontakt_privacy_label:'Ich stimme zu, dass meine Angaben aus dem Kontaktformular zur Beantwortung meiner Anfrage erhoben und verarbeitet werden. Hinweis: Du kannst Deine Einwilligung jederzeit für die Zukunft per E‑Mail widerrufen. Detaillierte Informationen findest Du in unserer <a href="Datenschutz.html" target="_blank" rel="noopener">Datenschutzerklärung</a>.',impressum_map_title:"Google Maps laden",impressum_map_text:'Um die interaktive Karte anzuzeigen, klicken Sie bitte auf "Karte laden". Dadurch stimmen Sie der Übertragung Ihrer IP-Adresse an Google und der Verarbeitung von Cookies gemäß der Datenschutzrichtlinien von Google zu. (Details in unserer <a href="Datenschutz.html" target="_blank" rel="noopener">Datenschutzerklärung</a>)',impressum_map_btn:"Karte laden",impressum_h_ddg:"Angaben gemäß § 5 DDG",impressum_h_contact:"Kontakt",impressum_contact_block:'Telefon: +49 (0) 163 2662435<br>E-Mail: <a href="mailto:manufaktur-malerei@web.de">manufaktur-malerei@web.de</a><br>Anschrift: Rüdesheimer Straße 14, 53175 Bonn',impressum_h_vat:"Umsatzsteuer",impressum_vat_text:"Gemäß § 19 Abs. 1 UStG (Kleinunternehmerregelung) wird keine Umsatzsteuer berechnet.",impressum_h_editor:"Redaktionell verantwortlich und Erstellung der Webseite",impressum_dev_credit:'Programmierung &amp; Design Code:<br><a href="https://github.com/Schengii?tab=repositories" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-github" aria-hidden="true"></i> Repository auf GitHub</a>',impressum_h_copyright:"Urheberrechtshinweis (Copyright Bildergalerie)",impressum_copyright_text:"Alle Bilder wurden selbst gemalt und dürfen nicht ohne ausdrückliche Erlaubnis weder verändert, öffentlich genutzt, noch kopiert werden.<br>*** Für die Bilder gilt ein Copyright durch die Künstlerin Manuela Schenk. *** <br>Die Bilder gehören der ManuFAKTUR, bei unrechtmäßiger Nutzung behalten wir uns rechtliche Schritte vor und bringen diese zur Anzeige.",impressum_h_eu:"EU-Streitschlichtung",impressum_eu_text:'Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: <a href="https://ec.europa.eu/consumers/odr/" target="_blank" rel="noopener noreferrer">https://ec.europa.eu/consumers/odr/</a>.<br> Unsere E-Mail-Adresse finden Sie oben im Impressum.',impressum_h_dispute:"Verbraucherstreitbeilegung / Universalschlichtungsstelle",impressum_dispute_text:"Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.",dsgvo_h1:"1. Datenschutz auf einen Blick",dsgvo_h1_1:"Allgemeine Hinweise",dsgvo_h1_1_text:"Die folgenden Hinweise geben einen einfachen Überblick darüber, was mit Ihren personenbezogenen Daten passiert, wenn Sie diese Website besuchen. Personenbezogene Daten sind alle Daten, mit denen Sie persönlich identifiziert werden können.",dsgvo_h1_2:"Datenerfassung auf unserer Website",dsgvo_h1_2_text1:"<strong>Wer ist verantwortlich für die Datenerfassung auf dieser Website?</strong><br>Die Datenverarbeitung auf dieser Website erfolgt durch die Websitebetreiberin Manuela Schenk (ManuFAKTUR). Die vollständigen Kontaktdaten können Sie dem Impressum dieser Website entnehmen.",dsgvo_h1_2_text2:"<strong>Wie erfassen wir Ihre Daten?</strong><br>Ihre Daten werden zum einen dadurch erhoben, dass Sie uns diese mitteilen (z. B. Daten, die Sie in das Kontaktformular eingeben). Andere Daten werden automatisch oder nach Ihrer ausdrücklichen Einwilligung beim Besuch der Website durch IT-Systeme erfasst. Das sind vor allem technische Daten (z. B. Internetbrowser, Betriebssystem oder Uhrzeit des Seitenaufrufs).",dsgvo_h2:"2. Hosting und Server-Log-Files",dsgvo_h2_text:"Wir hosten die Inhalte unserer Website bei Vercel. Der Hoster erhebt automatisch Informationen in sogenannten Server-Log-Dateien, die Ihr Browser automatisch an uns übermittelt (IP-Adresse, Browsertyp, Betriebssystem, Referrer URL, Hostname des zugreifenden Rechners, Uhrzeit der Serveranfrage). Diese Daten werden zur Gewährleistung eines sicheren und fehlerfreien Betriebs erhoben (Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO).",dsgvo_h2_analytics_h:"Vercel Web Analytics und Speed Insights",dsgvo_h2_analytics_text:"Wir nutzen Vercel Web Analytics und Vercel Speed Insights, um die Nutzung und die Ladegeschwindigkeit unserer Website auszuwerten. Die Dienste arbeiten ohne Cookies und ohne dauerhafte Kennung; Besucher werden nicht seitenübergreifend wiedererkannt. Erfasst werden anonymisierte Daten wie aufgerufene Seite, Referrer, Land, Browser, Betriebssystem, Gerätetyp sowie Messwerte zur Ladezeit. Die Auswertung erfolgt durch Vercel Inc. als Auftragsverarbeiter (Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse an einem stabilen und schnellen Webauftritt).",dsgvo_h3:"3. Lokale Einbindung von Schriftarten & Symbolen (DSGVO-konform)",dsgvo_h3_intro:"Um die Privatsphäre unserer Besucher bestmöglich zu schützen, nutzen wir keine externen CDNs (Content Delivery Networks) von Drittanbietern:",dsgvo_h3_li1:"<strong>Google Fonts:</strong> Alle verwendeten Schriften (Lato, Playfair Display, Dancing Script) sind lokal auf unserem Webserver gespeichert und werden von dort geladen. Es findet keine Verbindung zu Servern von Google statt.",dsgvo_h3_li2:"<strong>Font Awesome:</strong> Die verwendeten Icons und Stylesheets von Font Awesome sind ebenfalls vollständig lokal auf unserem Webserver gehostet. Es erfolgt kein Datentransfer zu Drittservern.",dsgvo_h4:"4. Einwilligungspflichtige Dienste von Drittanbietern",dsgvo_h4_1:"Google Maps (Zwei-Klick-Lösung)",dsgvo_h4_1_text:'Auf unserer Website ist eine Karte von Google Maps eingebunden. Um zu verhindern, dass bereits beim Laden der Seite Ihre IP-Adresse an Google übertragen wird, nutzen wir eine datenschutzfreundliche Zwei-Klick-Lösung. Die Karte ist standardmäßig deaktiviert. Erst wenn Sie aktiv auf die Schaltfläche "Karte laden" klicken, willigen Sie ein, dass eine Verbindung zu den Servern von Google (Google Ireland Limited) aufgebaut wird. Rechtsgrundlage für diese Verarbeitung ist Ihre Einwilligung gemäß Art. 6 Abs. 1 lit. a DSGVO. Sie können diese Einwilligung jederzeit für die Zukunft widerrufen.',dsgvo_h5:"5. Datenerfassung über das Kontaktformular & Web3Forms",dsgvo_h5_text1:"Wenn Sie uns per Kontaktformular Anfragen zukommen lassen, werden Ihre Angaben aus dem Formular inklusive der von Ihnen dort angegebenen Kontaktdaten zwecks Bearbeitung der Anfrage und für den Fall von Anschlussfragen bei uns verarbeitet.",dsgvo_h5_formspree:"Für die technische Übermittlung von Formularanfragen nutzen wir den Dienst <strong>Web3Forms</strong> (Web3Forms, c/o Surjith S M, India / Cloudflare infrastructure). Wenn Sie das Formular absenden, werden Ihre eingegebenen Daten verschlüsselt an die Server von Web3Forms übertragen und per E-Mail an uns weitergeleitet. Web3Forms speichert Ihre Formulardaten nicht dauerhaft in Datenbanken, sondern leitet diese direkt an unsere E-Mail-Adresse weiter. Rechtsgrundlage ist die Anbahnung oder Erfüllung eines Vertrags (Art. 6 Abs. 1 lit. b DSGVO) sowie unser berechtigtes Interesse an einer verlässlichen und spamgeschützten Bearbeitung von Kundenanfragen (Art. 6 Abs. 1 lit. f DSGVO).",dsgvo_h6:"6. Lokale Speicherung im Browser (LocalStorage gemäß § 25 Abs. 2 Nr. 2 TDDG)",dsgvo_h6_text:"Diese Website verwendet die lokale Speicherfunktion Ihres Browsers (LocalStorage). Wir speichern darin ausschließlich Ihre gewählte Spracheinstellung (manufaktur_lang), das gewünschte Farbdesign (manufaktur_theme) sowie Ihre persönliche Merkliste von Kunstwerken (manufaktur_favorites). Es werden keine Tracking-Cookies gesetzt und keine personenbezogenen Nutzungsprofile erstellt. Die Speicherung ist technisch erforderlich, um die von Ihnen ausdrücklich gewünschten Anzeigeeinstellungen sitzungsübergreifend bereitzustellen (§ 25 Abs. 2 Nr. 2 TDDG).",dsgvo_h7:"7. SSL- bzw. TLS-Verschlüsselung",dsgvo_h7_text:"Diese Seite nutzt aus Sicherheitsgründen und zum Schutz der Übertragung vertraulicher Inhalte, wie zum Beispiel Anfragen über das Kontaktformular, eine SSL- bzw. TLS-Verschlüsselung. Eine verschlüsselte Verbindung erkennen Sie daran, dass die Adresszeile des Browsers von „http://“ auf „https://“ wechselt und an dem Schloss-Symbol in Ihrer Browserzeile.",dsgvo_h8:"8. Ihre Rechte bezüglich Ihrer Daten",dsgvo_h8_text:"Sie haben im Rahmen der geltenden gesetzlichen Bestimmungen jederzeit folgende Rechte:<br>• <strong>Recht auf Auskunft (Art. 15 DSGVO):</strong> Sie können Auskunft über Ihre von uns verarbeiteten personenbezogenen Daten verlangen.<br>• <strong>Recht auf Berichtigung (Art. 16 DSGVO):</strong> Sie können die Berichtigung unrichtiger Daten verlangen.<br>• <strong>Recht auf Löschung (Art. 17 DSGVO):</strong> Sie können die Löschung Ihrer bei uns gespeicherten personenbezogenen Daten verlangen.<br>• <strong>Recht auf Einschränkung der Verarbeitung (Art. 18 DSGVO):</strong> Sie können die Einschränkung der Datenverarbeitung verlangen.<br>• <strong>Recht auf Datenübertragbarkeit (Art. 20 DSGVO):</strong> Sie können verlangen, Ihre Daten in einem strukturierten, gängigen Format zu erhalten.<br>• <strong>Widerspruchsrecht (Art. 21 DSGVO):</strong> Sie haben das Recht, jederzeit gegen die Verarbeitung Ihrer personenbezogenen Daten Widerspruch einzulegen.<br>• <strong>Widerruf Ihrer Einwilligung (Art. 7 Abs. 3 DSGVO):</strong> Sie können erteilte Einwilligungen jederzeit für die Zukunft per E-Mail widerrufen.<br>• <strong>Beschwerderecht bei der zuständigen Aufsichtsbehörde (Art. 77 DSGVO):</strong> Zuständige Aufsichtsbehörde ist die Landesbeauftragte für Datenschutz und Informationsfreiheit Nordrhein-Westfalen (LDI NRW), Kavalleriestraße 2–4, 40213 Düsseldorf.",auftrag_restore_text:'Du hast eine gespeicherte Konfiguration. <button type="button" id="restore-btn">Wiederherstellen</button> oder <button type="button" id="clear-btn">Neu starten</button>.',auftrag_fav_title:"Aus deinen gemerkten Favoriten wählen",auftrag_fav_hint:"Klicke auf eines deiner gemerkten Lieblingswerke, um es als Motiv-Inspiration zu übernehmen:",auftrag_motiv1_title:"Tierportrait",auftrag_motiv1_desc:"Hund, Katze, Pferd oder jedes andere Tier – als unvergängliches Gemälde.",auftrag_motiv2_title:"Landschaft",auftrag_motiv2_desc:"Ein besonderer Ort, eine Urlaubserinnerung oder eine traumhafte Szene.",auftrag_motiv3_title:"Stillleben / Pflanzen",auftrag_motiv3_desc:"Blumen, Früchte oder andere Objekte als dekoratives Gemälde.",auftrag_motiv4_title:"Sonstiges / Eigene Idee",auftrag_motiv4_desc:"Du hast eine ganz eigene Idee? Ich male nach deinem Wunschmotiv.",auftrag_motiv4_price:"Auf Anfrage",auftrag_hint1:"Bitte wähle ein Motiv, um fortzufahren.",auftrag_next_format:"Weiter: Format",auftrag_format1_small:"Klein",auftrag_format2_small:"Beliebt",auftrag_format3_small:"Mittel",auftrag_format4_small:"Groß",auftrag_format5_small:"XL",auftrag_format6_title:"Individuell",auftrag_format6_small:"Wunschformat · auf Anfrage",auftrag_hint2:"Bitte wähle ein Format, um fortzufahren.",auftrag_back:"Zurück",auftrag_next_technik:"Weiter: Technik",auftrag_tech1_title:"Acrylfarben",auftrag_tech1_desc:"Schnelle Trocknungszeit",auftrag_tech1_delivery:"Lieferung in einigen Wochen",auftrag_tech2_title:"Ölfarben",auftrag_tech2_desc:"längere Trocknungszeit",auftrag_tech2_delivery:"Lieferung in einigen Wochen",auftrag_hint3:"Bitte wähle eine Technik, um fortzufahren.",auftrag_next_summary:"Zur Zusammenfassung",auftrag_summary_motiv:"Motiv",auftrag_summary_format:"Format",auftrag_summary_technik:"Technik",auftrag_summary_lieferzeit:"Lieferzeit",auftrag_price_note:"* Endpreis nach individueller Absprache. Versand innerhalb DE kostenpflichtig.",auftrag_photo_h4:"Eigenes Fotovorlage-Bild auswählen (Optional)",auftrag_photo_hint:"Wähle hier dein Haustier- oder Landschaftsfoto aus, um es als Vorschau zu prüfen. Das Foto bleibt auf deinem Gerät und wird nicht mit der Anfrage übertragen.",auftrag_photo_input_label:"Fotovorlage auswählen",auftrag_photo_preview_alt:"Fotovorlage Vorschau",auftrag_photo_loaded:"Fotovorlage geladen",auftrag_photo_ready:"Bitte sende das Foto nach deiner Anfrage per E-Mail oder WhatsApp.",auftrag_summary_referenz:"Referenz",auftrag_submit:"Jetzt unverbindlich anfragen"},en:{skip_link:"Skip to main content",back_to_top:"Back to top",home_welcome_title:"Welcome",home_welcome_text:"Here my paintings come to life, all lovingly hand-painted by me in exquisite detail.<br>Quality and individuality are my hallmarks. I create custom animal portraits and landscapes for you.",badge_handpainted:"100% Hand-painted",badge_studio:"Studio in Bonn, Germany",badge_shipping:"Insured Shipping in DE",badge_detail:"Loving Attention to Detail",highlights_title:"Current Highlights",highlights_intro:"A curated selection of my newest original paintings.",testimonials_title:"What My Clients Say",testimonials_intro:"Genuine experiences & feedback from happy art enthusiasts:",cta_text:"Discover the collection of hand-painted originals or commission your very own personal motif.",about_page_title:"About Me",about_intro:"Get to know the artist behind the canvas.",about_profile_title:"Profile",about_lbl_loc:"Location:",about_lbl_dog:"Owner of:",about_lbl_motifs:"Motifs:",about_lbl_tech:"Techniques:",about_lbl_edu:"Education:",about_lbl_motive:"Motivation:",about_profile_loc:"Bonn (Bad Godesberg), Germany",about_profile_dog:"Balou",about_profile_motifs:"Animal portraits, favorite places & landscapes",about_profile_tech:"Acrylic, Oil, Oil Pastel, Mixed Media",about_profile_edu:"Alanus University Alfter, Art Studio Bonn-Friesdorf",about_profile_motive:"The joy of capturing vibrant emotions & living moments",about_greeting:"Hello, I am Manuela,",about_subtitle:"...artist from Bonn, dog lover and owner of Balou",about_p1:"I love capturing <strong>special moments</strong>, <strong>animals</strong> or <strong>landscapes</strong> with fine brushes and vivid pigments on high-grade canvas or handmade cotton paper.",about_p2:"My paintings tell heartfelt stories: whether the loyal gaze of a dog, the serenity of the French Atlantic coast, or historic impressions of my home city Bonn and the Siebengebirge.",about_p3:"I paint what inspires and touches me – in traditional <strong>oil painting</strong>, radiant <strong>acrylic colors</strong>, and nuanced <strong>oil pastel and mixed media techniques</strong>.",about_p4:"Every single artwork is a hand-painted unique original created with great attention to detail and proven artistic craftsmanship.",about_p5:'I would be delighted to paint your personal custom motif! Feel free to view my <a href="Leistungen.html">services</a> or contact me directly via the <a href="Kontakt.html">contact form</a>.',services_page_title:"Services & Techniques",services_intro:"Unique, custom artworks crafted according to your personal vision.",services_offer_title:"What I Offer",service_dog_title:"Your Dog on Canvas",service_dog_desc:"Have you always dreamed of a timeless portrait of your loyal four-legged companion? From white Maltese to black Labrador – every dog is a wonderful motif.",service_pets_title:"More Animal Companions",service_pets_desc:"Of course I do not only paint dogs! Cats, horses, parrots, wildlife and all animal friends make expressive, soulful paintings.",service_places_title:"Your Favorite Places",service_places_desc:"Special landscapes and cherished places hold their own magic. If you have such memories, I will transform them into lasting art on canvas.",service_formats_title:"Available Formats",service_formats_desc:"I offer a wide variety of custom sizes and proportions. Since every piece is painted with time and passion, I gladly provide a personal non-binding offer.",faq_title:"Frequently Asked Questions (FAQ)",faq_1_q:"What does a painting cost?",faq_1_a:"The price depends on the size of the painting. Payment is made in advance (incl. postage and packaging).",faq_2_q:"How long does it take to create a painting?",faq_2_a:"Depending on the technique (acrylic dries faster than oil) and current commissions, completion typically takes a few weeks. Please order well in advance for gifts!",faq_4_q_cancellation:"Right of Withdrawal for Custom Artworks",faq_4_a_cancellation:"For artworks created individually according to your personal wishes and specifications (such as pet portraits from photo references), there is no statutory right of withdrawal pursuant to § 312g (2) No. 1 German Civil Code (BGB), as the work is clearly tailored to you personally. However, before starting and throughout the painting process, I closely coordinate all details and milestones with you so that you will be completely thrilled with your finished painting.",gallery_page_title:"Art Gallery",gallery_intro:"Discover my hand-painted originals across diverse styles and creative periods.",filter_all:"All Works",filter_animals:"Animals",filter_landscapes:"Landscapes",filter_plants:"Botanicals",filter_other:"Still Life & More",filter_favorites:"Favorites",search_placeholder:"Search paintings, motifs, techniques or sizes...",sort_label:"Sort by:",sort_aria:"Sort gallery",sort_default:"Default",sort_newest:"Newest first",sort_title_asc:"Title (A-Z)",sort_title_desc:"Title (Z-A)",gallery_empty_fav_title:"No favorites saved yet.",gallery_empty_fav_text:"Click the heart icon on any artwork to save your personal favorites here.",gallery_empty_search_title:"No matching paintings found.",gallery_empty_search_text:"Try a different search term or reset the category filter.",scene_label:"AI Wall Preview:",scene_label_short:"AI Wall Preview",scene_living:"Living Room",scene_living_title:"Living Room Wall",scene_bedroom:"Bedroom",scene_bedroom_title:"Bedroom Wall",scene_loft:"Loft / Concrete",scene_loft_title:"Dark Loft Wall",scene_lounge:"Beige Lounge",scene_lounge_title:"Beige Lounge Wall",scene_pure:"Pure (Detail)",scene_pure_title:"Pure, No Background",wall_drag_hint:"Drag to Move",lb_rotate_title:"Rotate 90°",lb_rotate_aria:"Rotate image by 90 degrees",lb_zoom_title:"Activate/Deactivate Magnifier",lb_zoom_aria:"Activate magnifier",lb_scale_label:"Scale:",lb_scale_aria:"Scale the painting's size on the wall",lb_center_title:"Center the painting position on the wall",lb_label_technik:"Technique:",lb_label_masse:"Size / Format:",lb_label_kat:"Category:",lb_label_herkunft:"Origin:",lb_val_herkunft:"Studio Bonn",lb_label_rahmung:"Framing:",lb_label_status:"Availability:",status_verfuegbar:"Available",status_reserviert:"Reserved",status_verkauft:"Sold – I am happy to paint a similar motif for you",lb_val_rahmung:"Ready to Hang (Stretcher Frame)",lb_views_title:"More Views:",lb_view_front:"Front View",lb_view_front_title:"Pure Front View",lb_view_room:"Wall View",lb_view_room_title:"Wall & Room View",lb_view_back:"Back",lb_view_back_title:"Back & Stretcher Frame",lb_view_side:"3D Perspective",lb_view_side_title:"3D Side View & Texture",lb_view_artist:"Studio",lb_view_artist_title:"Artist & Studio",lb_inquiry_aria:"Request this motif as a commission",lb_fav_default:"Favorite",clear_search_aria:"Clear search",lb_btn_inquiry:"Inquire this Motif as Commission",lb_btn_room:"View in Your Room",lb_btn_fav_add:"Add to Favorites",lb_btn_fav_remove:"Remove from Favorites",lb_share_btn:"Share Artwork",lb_share_aria:"Share artwork",lb_rotate:"Rotate 90°",lb_zoom:"Magnifier Zoom",lb_center:"Center",order_page_title:"Configure Commission",order_intro:"In just 4 simple steps to your custom artwork – receive a non-binding price estimate and submit your request directly.",step_1_lbl:"Motif",step_2_lbl:"Size",step_3_lbl:"Medium",step_4_lbl:"Summary",step_1_heading:"Step 1: Choose Your Motif",step_1_sub:"What would you like to have painted on your unique artwork?",step_2_heading:"Step 2: Choose Your Format & Size",step_2_sub:"Which canvas dimensions suit your space best?",step_3_heading:"Step 3: Choose Your Medium & Technique",step_3_sub:"Which medium and artistic texture appeals most to you?",step_4_heading:"Step 4: Summary & Inquiry",step_4_sub:"Review your selected configuration and submit your non-binding inquiry directly to Manuela.",contact_page_title:"Contact",contact_intro:"I look forward to hearing from you, whether with questions regarding existing artworks or commission requests.",contact_btn_send:"Send Message",map_title:"Activate Google Maps",map_text:"For privacy reasons, the interactive map is only loaded after your consent click.",map_btn:"Load Map",imprint_page_title:"Imprint",privacy_page_title:"Privacy Policy",notfound_title:"404 – Page Not Found",notfound_text:"This canvas is still empty. The page you are looking for does not exist (anymore) or has been moved.",notfound_btn:"Back to Home",notfound_btn2:"To the Gallery",ui_close:"Close",ui_prev_image:"Previous Image",ui_next_image:"Next Image",ui_lightbox_label:"Enlarged Image View",hl_owls_aria:"Enlarge: Two Owls",hl_owls_alt:"Hand-painted acrylic painting of two small owls on a branch against a blue background",hl_owls_caption:"Two Owls (Acrylic on Canvas)",hl_godesburg_aria:"Enlarge: Godesburg Cityscape",hl_godesburg_alt:"Hand-painted landscape of the historic Godesburg castle in Bonn at dusk",hl_godesburg_caption:"Godesburg Cityscape (Acrylic on Canvas)",hl_rheinaue_aria:"Enlarge: Rheinaue Bonn",hl_rheinaue_alt:"Hand-painted acrylic painting of the autumnal Rheinaue lake in Bonn with trees and reflections",hl_rheinaue_caption:"Rheinaue Bonn (Acrylic on Canvas)",hl_feld_aria:"Enlarge: Field Path",hl_feld_alt:"Hand-painted acrylic painting of an idyllic field path in summer under a blue sky",hl_feld_caption:"Field Path in Summer (Acrylic on Canvas)",testi1_quote:'"The portrait of our German Shepherd Balou turned out simply fantastic. Manuela captured his loyal gaze perfectly. We are overjoyed!"',testi1_author:"– Delighted Client Family",testi1_location:"Bonn-Bad Godesberg · Animal Portrait in Acrylic",testi2_quote:'"I ordered a landscape painting of the Rheinaue as a wedding gift. The coordination was super easy, and the bride and groom were moved to tears."',testi2_author:"– A Client",testi2_location:"Rhein-Sieg District · Landscape Painting",testi3_quote:'"Beautiful work! You can feel the love for detail in every brushstroke. The painting now has a central place of honor in our living room."',testi3_author:"– A Client",testi3_location:"Cologne · Dog Portrait & Still Life",testi_prev_aria:"Previous testimonial",testi_next_aria:"Next testimonial",testi_pause_aria:"Pause automatic rotation",testi_stars_aria:"5 out of 5 stars",testi_dot_1:"Show testimonial 1",testi_dot_2:"Show testimonial 2",testi_dot_3:"Show testimonial 3",home_btn_gallery:"View Gallery",home_btn_flyer:"Flyer Download",process_h2:"How Each Artwork Is Created",process_intro:"Art for your home",process1_title:"Creating several sketches",process1_text:"Precise transfer of your photo motif onto the canvas as a fine preliminary sketch.",process2_title:"Various layers of color",process2_text:"Applying the first layers of paint for depth, shadow and characteristic highlights.",process3_title:"Finest detailing",process3_text:"Fine detailing of eyes, fur texture or light reflections, followed by the final sealing.",edu_h2:"Artistic Training & Instructors",edu_intro:"A solid craft built through continuous training at recognized art academies:",edu1_place:"Alfter near Bonn",edu1_text:'The year-long course <em>"A Year for the Arts"</em> as well as in-depth seminars and intensive weeks for artistic professionalization.',edu1_dozenten_label:"Instructors:",edu2_place:"Bad Godesberg · Friesdorf",edu2_text:"Intensive private lessons in advanced painting techniques, color theory, brushwork and composition.",edu3_place:"Aachen & Bonn",edu3_text:"Specialized courses in figure drawing, portrait painting, landscape studies and classical oil and acrylic painting.",tl5_title:"Art for Your Home",tl5_text:"With many individual originals and many happy clients, I create lasting value and personal keepsakes.",flyer_h2:"My Info Flyer",flyer_text:"Click on an image for a larger view or download the flyer as a PDF.",flyer_front_alt:"Front side of the ManuFAKTUR Schenk information flyer",flyer_back_alt:"Back side of the ManuFAKTUR Schenk information flyer",flyer_btn:"Download Flyer (PDF)",faq_3_q_ship:"Shipping",faq_3_a_ship:"Once finished and fully dry, I ship your painting by post. Exact shipping costs are individually coordinated in advance.",leist_cta_text:"Do you have further questions or your own wishes?",leist_cta_btn1:"Configure Commission",leist_cta_btn2:"I'd Love to Hear From You!",kontakt_vcard_title:"Digital Business Card",kontakt_vcard_hint:"Move your mouse over the card or tap it to flip it.",kontakt_vcard_aria:"Digital business card of Manuela Schenk. Press Enter or Space to flip.",kontakt_vcard_badge:"Business Card",kontakt_vcard_role:"Artist & Owner",kontakt_vcard_save:"Save Contact (.vcf)",kontakt_vcard_pdf:"Business Card (PDF)",kontakt_city:"Bonn, Germany",kontakt_address:"53175 Bonn, Germany",social_ig_label:"Follow me on Instagram",social_wa_label:"Message me on WhatsApp",kontakt_prefill_text:"<strong>Your configuration has been transferred!</strong> The form has been pre-filled with your selections from the configurator.",kontakt_label_name:"Your Name",kontakt_ph_name:"What should we call you?",kontakt_label_email:"Your Email Address",kontakt_ph_email:"your.name@example.com",kontakt_label_subject:"Subject",kontakt_opt_general:"General Inquiry",kontakt_opt_animal:"Commission: Animal Portrait",kontakt_opt_landscape:"Commission: Landscape",kontakt_opt_purchase:"Interested in Purchasing a Painting",kontakt_label_message:"Your Message:",kontakt_ph_message:"Your message...",kontakt_privacy_label:'I agree that my details from the contact form will be collected and processed to answer my inquiry. Note: You can revoke your consent at any time for the future by email. Detailed information can be found in our <a href="Datenschutz.html" target="_blank" rel="noopener">Privacy Policy</a>.',impressum_map_title:"Load Google Maps",impressum_map_text:'To display the interactive map, please click "Load Map". By doing so, you consent to the transmission of your IP address to Google and the processing of cookies in accordance with Google\'s privacy policies. (Details in our <a href="Datenschutz.html" target="_blank" rel="noopener">Privacy Policy</a>)',impressum_map_btn:"Load Map",impressum_h_ddg:"Information pursuant to § 5 DDG (Digital Services Act)",impressum_h_contact:"Contact",impressum_contact_block:'Phone: +49 (0) 163 2662435<br>Email: <a href="mailto:manufaktur-malerei@web.de">manufaktur-malerei@web.de</a><br>Address: Rüdesheimer Straße 14, 53175 Bonn, Germany',impressum_h_vat:"VAT",impressum_vat_text:"Pursuant to § 19 (1) of the German VAT Act (UStG – small business regulation), no VAT is charged.",impressum_h_editor:"Editorially Responsible and Website Creation",impressum_dev_credit:'Programming &amp; Design Code:<br><a href="https://github.com/Schengii?tab=repositories" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-github" aria-hidden="true"></i> Repository on GitHub</a>',impressum_h_copyright:"Copyright Notice (Gallery Images)",impressum_copyright_text:"All paintings were hand-painted by the artist herself and may not be modified, publicly used, or copied without her explicit permission.<br>*** All images are copyrighted by the artist Manuela Schenk. *** <br>The images belong to ManuFAKTUR; in the event of unlawful use, we reserve the right to take legal action.",impressum_h_eu:"EU Dispute Resolution",impressum_eu_text:'The European Commission provides a platform for online dispute resolution (ODR): <a href="https://ec.europa.eu/consumers/odr/" target="_blank" rel="noopener noreferrer">https://ec.europa.eu/consumers/odr/</a>.<br> Our email address can be found above in this legal notice.',impressum_h_dispute:"Consumer Dispute Resolution",impressum_dispute_text:"We are not willing or obliged to participate in dispute resolution proceedings before a consumer arbitration board.",dsgvo_h1:"1. Privacy at a Glance",dsgvo_h1_1:"General Information",dsgvo_h1_1_text:"The following information provides a simple overview of what happens to your personal data when you visit this website. Personal data is any data that can be used to personally identify you.",dsgvo_h1_2:"Data Collection on Our Website",dsgvo_h1_2_text1:"<strong>Who is responsible for data collection on this website?</strong><br>Data processing on this website is carried out by the website operator Manuela Schenk (ManuFAKTUR), whose full contact details can be found in the legal notice (Impressum) of this website.",dsgvo_h1_2_text2:"<strong>How do we collect your data?</strong><br>Your data is collected in part when you provide it to us (e.g. data you enter into the contact form). Other data is collected automatically, or after your consent, by IT systems when you visit the website. This is primarily technical data (e.g. internet browser, operating system, or time of page access).",dsgvo_h2:"2. Hosting and Server Log Files",dsgvo_h2_text:"We host our website content with Vercel. The host automatically collects information in so-called server log files, which your browser automatically transmits to us (IP address, browser type, operating system, referrer URL, host name of accessing machine, time of server request). This data is collected to ensure secure and trouble-free operation (Legal basis: Art. 6 (1)(f) GDPR).",dsgvo_h2_analytics_h:"Vercel Web Analytics and Speed Insights",dsgvo_h2_analytics_text:"We use Vercel Web Analytics and Vercel Speed Insights to evaluate the use and loading speed of our website. The services work without cookies and without a persistent identifier; visitors are not recognised across pages. Anonymised data such as the page viewed, referrer, country, browser, operating system, device type and loading-time measurements is collected. The evaluation is carried out by Vercel Inc. as a processor (legal basis: Art. 6(1)(f) GDPR, legitimate interest in a stable and fast website).",dsgvo_h3:"3. Local Integration of Fonts & Icons (GDPR-compliant)",dsgvo_h3_intro:"To best protect the privacy of our visitors, we do not use third-party CDNs (Content Delivery Networks) for fonts or icons:",dsgvo_h3_li1:"<strong>Google Fonts:</strong> All fonts used (Lato, Playfair Display, Dancing Script) are stored locally on our web server and loaded from there. There is no connection to Google's servers.",dsgvo_h3_li2:"<strong>Font Awesome:</strong> The Font Awesome icons and stylesheets used are likewise hosted locally on our web server. No data is transferred to third-party servers.",dsgvo_h4:"4. Third-Party Services Requiring Consent",dsgvo_h4_1:"Google Maps (Two-Click Solution)",dsgvo_h4_1_text:'Our website includes a Google Maps map. To prevent your IP address from being transmitted to Google as soon as the page loads, we use a privacy-friendly two-click solution. The map is disabled by default. Only when you actively click the "Load Map" button do you consent to a connection being established with Google\'s servers (Google Ireland Limited). The legal basis for this processing is your consent pursuant to Art. 6 (1)(a) GDPR. You can revoke this consent at any time for the future.',dsgvo_h5:"5. Data Collection via the Contact Form & Web3Forms",dsgvo_h5_text1:"If you send us inquiries via the contact form, the information you provide there, including any contact details you enter, will be processed by us for the purpose of handling your inquiry and in case of follow-up questions.",dsgvo_h5_formspree:"For the technical transmission of form inquiries, we use the service <strong>Web3Forms</strong> (Web3Forms, c/o Surjith S M, India / Cloudflare infrastructure). When you submit the form, your entered data is transmitted in encrypted form to Web3Forms' servers and forwarded to us by email. Web3Forms does not permanently store form submissions in databases, forwarding them directly to our email address. The legal basis is the initiation or performance of a contract (Art. 6 (1)(b) GDPR) and our legitimate interest in the reliable and spam-protected handling of customer inquiries (Art. 6 (1)(f) GDPR).",dsgvo_h6:"6. Local Storage in Browser (LocalStorage pursuant to § 25 (2) No. 2 TDDG)",dsgvo_h6_text:"This website uses your browser's local storage function (LocalStorage). We solely store your chosen language preference (manufaktur_lang), selected color theme (manufaktur_theme), and your personal favorites wishlist of artworks (manufaktur_favorites). No tracking cookies are set and no personal user profiles are created. Storage is technically necessary to provide your explicitly requested display settings across sessions (§ 25 (2) No. 2 TDDG).",dsgvo_h7:"7. SSL / TLS Encryption",dsgvo_h7_text:'For security reasons and to protect the transmission of confidential content, such as inquiries via the contact form, this site uses SSL or TLS encryption. You can recognize an encrypted connection by the change in the browser address line from "http://" to "https://" and by the lock symbol in your browser bar.',dsgvo_h8:"8. Your Rights Regarding Your Data",dsgvo_h8_text:"Under applicable statutory provisions, you have the following rights at any time:<br>• <strong>Right of access (Art. 15 GDPR):</strong> You can request information about your personal data processed by us.<br>• <strong>Right to rectification (Art. 16 GDPR):</strong> You can request the correction of inaccurate data.<br>• <strong>Right to erasure (Art. 17 GDPR):</strong> You can request the deletion of your personal data stored with us.<br>• <strong>Right to restriction of processing (Art. 18 GDPR):</strong> You can request the restriction of data processing.<br>• <strong>Right to data portability (Art. 20 GDPR):</strong> You can request to receive your data in a structured, commonly used format.<br>• <strong>Right to object (Art. 21 GDPR):</strong> You have the right to object at any time to the processing of your personal data.<br>• <strong>Revocation of your consent (Art. 7 (3) GDPR):</strong> You can revoke given consent at any time for the future via email.<br>• <strong>Right to lodge a complaint with a supervisory authority (Art. 77 GDPR):</strong> The competent supervisory authority is the State Commissioner for Data Protection and Freedom of Information of North Rhine-Westphalia (LDI NRW), Kavalleriestraße 2–4, 40213 Düsseldorf, Germany.",auftrag_restore_text:'You have a saved configuration. <button type="button" id="restore-btn">Restore</button> or <button type="button" id="clear-btn">Start Over</button>.',auftrag_fav_title:"Choose from Your Saved Favorites",auftrag_fav_hint:"Click one of your saved favorite artworks to use it as motif inspiration:",auftrag_motiv1_title:"Animal Portrait",auftrag_motiv1_desc:"Dog, cat, horse or any other animal – as an everlasting painting.",auftrag_motiv2_title:"Landscape",auftrag_motiv2_desc:"A special place, a holiday memory, or a dreamlike scene.",auftrag_motiv3_title:"Still Life / Plants",auftrag_motiv3_desc:"Flowers, fruit, or other objects as a decorative painting.",auftrag_motiv4_title:"Other / Custom Idea",auftrag_motiv4_desc:"Do you have your own idea? I paint according to your desired motif.",auftrag_motiv4_price:"Upon Request",auftrag_hint1:"Please choose a motif to continue.",auftrag_next_format:"Next: Format",auftrag_format1_small:"Small",auftrag_format2_small:"Popular",auftrag_format3_small:"Medium",auftrag_format4_small:"Large",auftrag_format5_small:"XL",auftrag_format6_title:"Custom",auftrag_format6_small:"Custom size · upon request",auftrag_hint2:"Please choose a format to continue.",auftrag_back:"Back",auftrag_next_technik:"Next: Technique",auftrag_tech1_title:"Acrylic Paint",auftrag_tech1_desc:"Fast drying time",auftrag_tech1_delivery:"Delivery in a few weeks",auftrag_tech2_title:"Oil Paint",auftrag_tech2_desc:"longer drying time",auftrag_tech2_delivery:"Delivery in a few weeks",auftrag_hint3:"Please choose a technique to continue.",auftrag_next_summary:"To the Summary",auftrag_summary_motiv:"Motif",auftrag_summary_format:"Format",auftrag_summary_technik:"Technique",auftrag_summary_lieferzeit:"Delivery Time",auftrag_price_note:"* Final price subject to individual agreement. Shipping within Germany subject to charge.",auftrag_photo_h4:"Select Your Own Photo Reference (Optional)",auftrag_photo_hint:"Select your pet or landscape photo here to preview it. The photo stays on your device and is not transmitted with the inquiry.",auftrag_photo_input_label:"Select photo reference",auftrag_photo_preview_alt:"Photo reference preview",auftrag_photo_loaded:"Photo reference loaded",auftrag_photo_ready:"Please send the photo by email or WhatsApp after your inquiry.",auftrag_summary_referenz:"Reference",auftrag_submit:"Send Non-Binding Inquiry Now"}};